        IF kmd = 8 THEN tillstand := 8;
        ELSIF kmd = 1 THEN tillstand := 15; END_IF;
    3:  (* Starting *)
        IF kmd = 8 THEN tillstand := 8;
        ELSIF kmd = 3 THEN tillstand := 7;
        ELSIF trigSc.Q THEN tillstand := 6; END_IF;
    4:  (* Idle *)
        IF kmd = 8 THEN tillstand := 8;
        ELSIF kmd = 3 THEN tillstand := 7;
        ELSIF kmd = 2 THEN tillstand := 3; END_IF;
    5:  (* Suspended *)
        IF kmd = 8 THEN tillstand := 8;
        ELSIF kmd = 3 THEN tillstand := 7;
        ELSIF kmd = 7 THEN tillstand := 14; END_IF;
    6:  (* Execute *)
        IF kmd = 8 THEN tillstand := 8;
        ELSIF kmd = 3 THEN tillstand := 7;
        ELSIF kmd = 4 THEN tillstand := 10;
        ELSIF kmd = 6 THEN tillstand := 10;
        ELSIF trigSc.Q THEN tillstand := 16; END_IF;
    7:  (* Stopping *)
        IF kmd = 8 THEN tillstand := 8;
        ELSIF trigSc.Q THEN tillstand := 2; END_IF;
    8:  (* Aborting *)
        IF trigSc.Q THEN tillstand := 9; END_IF;
    9:  (* Aborted *)
        IF kmd = 9 THEN tillstand := 1; END_IF;
    10: (* Holding *)
        IF kmd = 8 THEN tillstand := 8;
        ELSIF kmd = 3 THEN tillstand := 7;
        ELSIF trigSc.Q THEN tillstand := 11; END_IF;
    11: (* Held *)
        IF kmd = 8 THEN tillstand := 8;
        ELSIF kmd = 3 THEN tillstand := 7;
        ELSIF kmd = 5 THEN tillstand := 12; END_IF;
    12: (* Unholding *)
        IF kmd = 8 THEN tillstand := 8;
        ELSIF kmd = 3 THEN tillstand := 7;
        ELSIF trigSc.Q THEN tillstand := 6; END_IF;
    13: (* Suspending *)
        IF kmd = 8 THEN tillstand := 8;
        ELSIF kmd = 3 THEN tillstand := 7;
        ELSIF trigSc.Q THEN tillstand := 5; END_IF;
    14: (* Unsuspending *)
        IF kmd = 8 THEN tillstand := 8;
        ELSIF kmd = 3 THEN tillstand := 7;
        ELSIF trigSc.Q THEN tillstand := 6; END_IF;
    15: (* Resetting *)
        IF kmd = 8 THEN tillstand := 8;
        ELSIF kmd = 3 THEN tillstand := 7;
        ELSIF trigSc.Q THEN tillstand := 4; END_IF;
    16: (* Completing *)
        IF kmd = 8 THEN tillstand := 8;
        ELSIF kmd = 3 THEN tillstand := 7;
        ELSIF trigSc.Q THEN tillstand := 17; END_IF;
    17: (* Complete *)
        IF kmd = 8 THEN tillstand := 8;
        ELSIF kmd = 3 THEN tillstand := 7;
        ELSIF kmd = 1 THEN tillstand := 15; END_IF;
END_CASE;

ST200_PML_STATE := tillstand;

(* Bandet gar bara i EXECUTE. Varken STARTING, HELD eller SUSPENDED ar drift. *)
ST200_CNV_RUN := tillstand = 6;
ST200_DIV_OPEN := (tillstand = 6) AND (ST200_HGT_MM > 120.0);
SYS_ALARM := (tillstand = 8) OR (tillstand = 9);
END_PROGRAM
